input.command:
$ErrorActionPreference = 'Continue';
$root = 'C:\Users\saleh\.cursor\projects\empty-window';
$log = Join-Path $root 'deploy-live-log.txt';
Set-Location $root;
if (Test-Path $log) { Remove-Item $log -Force }
New-Item -ItemType File -Path $log -Force | Out-Null

function Write-LogLine {
    param([string]$Text)
    Add-Content -Path $log -Value $Text
}

function Write-LogBlock {
    param([string]$Text)
    if ([string]::IsNullOrEmpty($Text)) {
        Write-LogLine '[no output]'
    } else {
        Add-Content -Path $log -Value $Text.TrimEnd("`r", "`n")
    }
}

function Run-ExternalCommand {
    param(
        [string]$CommandText,
        [scriptblock]$CommandBlock,
        [switch]$IgnoreExitCode
    )

    Write-LogLine "COMMAND: $CommandText"
    try {
        $output = & $CommandBlock 2>&1 | Out-String -Width 4096
        Write-LogBlock $output
        $exitCode = $LASTEXITCODE
        if ($null -eq $exitCode) { $exitCode = 0 }
        Write-LogLine "EXIT CODE: $exitCode"
    } catch {
        Write-LogBlock ($_ | Out-String -Width 4096)
        Write-LogLine 'EXIT CODE: exception'
    }
    Write-LogLine ''
}

function Run-PowerShellCommand {
    param(
        [string]$CommandText,
        [scriptblock]$CommandBlock
    )

    Write-LogLine "COMMAND: $CommandText"
    try {
        $output = & $CommandBlock | Out-String -Width 4096
        Write-LogBlock $output
        Write-LogLine 'EXIT CODE: 0'
    } catch {
        Write-LogBlock ($_ | Out-String -Width 4096)
        Write-LogLine 'EXIT CODE: exception'
    }
    Write-LogLine ''
}

function Run-WebRequest {
    param(
        [string]$CommandText,
        [string]$Url
    )

    Write-LogLine "COMMAND: $CommandText"
    try {
        $response = Invoke-WebRequest -Uri $Url -UseBasicParsing -ErrorAction Stop
        Write-LogLine "StatusCode: $($response.StatusCode)"
        Write-LogLine "StatusDescription: $($response.StatusDescription)"
        Write-LogLine 'EXIT CODE: 0'
    } catch {
        Write-LogBlock ($_ | Out-String -Width 4096)
        if ($_.Exception.Response) {
            try {
                Write-LogLine "StatusCode: $([int]$_.Exception.Response.StatusCode)"
                Write-LogLine "StatusDescription: $($_.Exception.Response.StatusDescription)"
            } catch {
            }
        }
        Write-LogLine 'EXIT CODE: exception'
    }
    Write-LogLine ''
}

Run-PowerShellCommand 'pwd' { (Get-Location).Path }
Run-PowerShellCommand 'dir (first 40 lines)' {
    $dirOutput = dir | Out-String -Width 4096
    ($dirOutput -split "`r?`n") | Select-Object -First 40
}
Run-ExternalCommand 'git status' { git status }
Run-ExternalCommand 'git remote -v' { git remote -v }
Run-ExternalCommand 'gh auth status' { gh auth status }

if (-not (Test-Path (Join-Path $root '.git'))) {
    Run-ExternalCommand 'git init' { git init }
}

Run-ExternalCommand 'git add -A' { git add -A }

$statusPorcelain = ''
try {
    $statusPorcelain = (git status --porcelain 2>&1 | Out-String -Width 4096).Trim()
} catch {
    $statusPorcelain = ''
}
if ([string]::IsNullOrWhiteSpace($statusPorcelain)) {
    Run-ExternalCommand 'git commit --allow-empty -m "Live deploy"' { git commit --allow-empty -m 'Live deploy' }
} else {
    Run-ExternalCommand 'git commit -m "Live deploy"' { git commit -m 'Live deploy' }
}

Run-ExternalCommand 'git branch -M main' { git branch -M main }
Run-ExternalCommand 'git remote remove origin' { git remote remove origin }
Run-ExternalCommand 'git remote add origin https://github.com/saleh-b-90-hub/ucarsmotors-site.git' { git remote add origin 'https://github.com/saleh-b-90-hub/ucarsmotors-site.git' }
Run-ExternalCommand 'git push -u origin main' { git push -u origin main }
Run-WebRequest 'Invoke-WebRequest https://raw.githubusercontent.com/saleh-b-90-hub/ucarsmotors-site/main/index.html' 'https://raw.githubusercontent.com/saleh-b-90-hub/ucarsmotors-site/main/index.html'
Run-ExternalCommand 'npx vercel --prod --yes' { npx vercel --prod --yes }
Run-WebRequest 'Invoke-WebRequest https://ucarsmotors-site.vercel.app' 'https://ucarsmotors-site.vercel.app'
Run-WebRequest 'Invoke-WebRequest https://www.ucarsmotors.com' 'https://www.ucarsmotors.com'
